from __future__ import annotations

from types import SimpleNamespace
from typing import Any

import pytest
from fastapi import FastAPI
from fastapi.testclient import TestClient

from backend.routers import model_gateway_router
from backend.routers.model_gateway_router import router


def _build_app() -> FastAPI:
    app = FastAPI()
    app.include_router(router)
    # Override auth dependency functions generated by require_permission(...) for all model-gateway routes.
    for route in app.routes:
        path = getattr(route, "path", "")
        if not path.startswith("/api/aix/model-gateway/"):
            continue
        deps = getattr(route, "dependant", None)
        if not deps or not deps.dependencies:
            continue
        auth_dep = deps.dependencies[0].call
        app.dependency_overrides[auth_dep] = lambda: {"id": "user-1", "tenant_id": "default"}
    return app


def _build_app_with_user(user: dict) -> FastAPI:
    app = FastAPI()
    app.include_router(router)
    for route in app.routes:
        path = getattr(route, "path", "")
        if not path.startswith("/api/aix/model-gateway/"):
            continue
        deps = getattr(route, "dependant", None)
        if not deps or not deps.dependencies:
            continue
        auth_dep = deps.dependencies[0]
        if not auth_dep.dependencies:
            continue
        current_user_dep = auth_dep.dependencies[0].call
        app.dependency_overrides[current_user_dep] = lambda: user
    return app


async def _codeintel_ok(**_kwargs):
    return {"index_jobs": [], "index_jobs_total": 0, "citations": []}, None


class _ModelRecord(SimpleNamespace):
    def model_dump(self) -> dict[str, Any]:
        return dict(self.__dict__)


