def test_sync_registry_from_integration_backfills_canonical_rows(monkeypatch) -> None:
    app = _build_app()
    calls: dict[str, list[dict[str, Any]]] = {"bindings_create": [], "health_create": []}

    async def _tenant(_current_user):
        return "default"

    class _Response:
        status_code = 200

        def json(self):
            return {
                "success": True,
                "data": {
                    "providers": [
                        {
                            "provider": "openrouter",
                            "endpoint_id": "endpoint-1",
                            "endpoint_name": "openrouter-llm-endpoint-admin",
                            "status": "active",
                            "configured": True,
                            "adapter_registered": True,
                            "missing_keys": [],
                            "credential_source": "integration_endpoints",
                            "source_of_truth": "integration_endpoints",
                            "migration_required": False,
                            "config_masked": {
                                "model": "openai/gpt-4o",
                                "api_key": "********1234",
                            },
                        },
                        {
                            "provider": "openai",
                            "status": "active",
                            "configured": True,
                            "adapter_registered": True,
                            "missing_keys": [],
                            "credential_source": "integration_endpoints",
                            "source_of_truth": "integration_endpoints",
                            "migration_required": False,
                            "config_masked": {},
                        },
                    ]
                },
            }

    class _AsyncClient:
        def __init__(self, **_kwargs):
            pass

        async def __aenter__(self):
            return self

        async def __aexit__(self, *_args):
            return None

        async def get(self, url, headers):
            assert url.endswith("/api/integrations/llm/admin/providers")
            assert headers["Authorization"] == "Bearer token-1"
            assert headers["X-Tenant-ID"] == "default"
            assert headers["X-Hyeve-Tenant-Id"] == "default"
            return _Response()

    async def _list_empty(**_kwargs):
        return {"items": []}

    async def _create_binding(*, data, **_kwargs):
        calls["bindings_create"].append(data.model_dump())
        return data

    async def _create_health(*, data, **_kwargs):
        calls["health_create"].append(data.model_dump())
        return data

    monkeypatch.setattr("backend.routers.model_gateway_router.validate_tenant_access", _tenant)
    monkeypatch.setattr("backend.routers.model_gateway_router.httpx.AsyncClient", _AsyncClient)
    monkeypatch.setattr("backend.routers.model_gateway_router.aix_model_provider_bindings_service.list", _list_empty)
    monkeypatch.setattr(
        "backend.routers.model_gateway_router.aix_model_provider_bindings_service.create", _create_binding
    )
    monkeypatch.setattr("backend.routers.model_gateway_router.aix_model_health_status_service.list", _list_empty)
    monkeypatch.setattr("backend.routers.model_gateway_router.aix_model_health_status_service.create", _create_health)

    with TestClient(app) as client:
        response = client.post(
            "/api/aix/model-gateway/registry/sync-from-integration",
            headers={"Authorization": "Bearer token-1"},
        )

    assert response.status_code == 200
    payload = response.json()["data"]
    assert payload["provider_rows_seen"] == 2
    assert payload["bindings_created"] == 1
    assert payload["health_created"] == 1
    assert payload["skipped"] == [{"provider": "openai", "reason": "missing_default_model"}]
    assert calls["bindings_create"][0]["provider"] == "openrouter"
    assert calls["bindings_create"][0]["model_id"] == "openai/gpt-4o"
    assert calls["bindings_create"][0]["model_name"] == "gpt-4o"
    assert "config_masked" not in calls["bindings_create"][0]["metadata_json"]
    assert calls["health_create"][0]["health_status"] == "unknown"
    assert calls["health_create"][0]["details_json"]["health_claim"] == "not_tested_by_sync"


